"""C++ · referencia completa (etapas 6 y 7). Los programas completos se compilan para calcular su salida."""
from .tabla import filas

E6 = filas(r"""
unordered_map ¦ unordered_map ¦ mapa con acceso muy rápido sin orden ¦ contar palabras ¦ #include <iostream>⏎#include <unordered_map>⏎int main() {⏎    std::unordered_map<std::string, int> c;⏎    for (auto p : {"a", "b", "a"}) c[p]++;⏎    std::cout << c["a"] << "\n";⏎} ¦ cuenta cuántas veces aparece a ¦ esperar que se recorra en orden
unordered_set ¦ unordered_set ¦ conjunto rápido de valores únicos ¦ quitar repetidos de una lista ¦ #include <iostream>⏎#include <unordered_set>⏎int main() {⏎    std::unordered_set<int> u{1, 2, 2, 3};⏎    std::cout << u.size() << " " << u.count(2) << "\n";⏎} ¦ guarda valores sin repetir ¦ usar find con vector cuando un set es más rápido
deque ¦ deque ¦ contenedor que agrega rápido por los dos extremos ¦ manejar una cola de turnos ¦ #include <iostream>⏎#include <deque>⏎int main() {⏎    std::deque<int> d{2, 3};⏎    d.push_front(1); d.push_back(4);⏎    std::cout << d.front() << " " << d.back() << "\n";⏎} ¦ agrega al inicio y al final ¦ usar vector con insert al inicio
stack y queue ¦ std::stack ¦ adaptadores de pila y cola ¦ deshacer acciones en orden inverso ¦ #include <iostream>⏎#include <stack>⏎int main() {⏎    std::stack<std::string> s;⏎    s.push("escribir"); s.push("borrar");⏎    std::cout << s.top() << "\n";⏎} ¦ muestra la última acción ¦ llamar top en una pila vacía
priority_queue ¦ priority_queue ¦ cola que entrega primero el mayor elemento ¦ atender primero las tareas urgentes ¦ #include <iostream>⏎#include <queue>⏎int main() {⏎    std::priority_queue<int> pq;⏎    for (int x : {3, 9, 1}) pq.push(x);⏎    std::cout << pq.top() << "\n";⏎} ¦ entrega primero el 9 ¦ olvidar que por defecto sale el mayor
Algoritmos find e count ¦ std::find ¦ algoritmos para buscar y contar en contenedores ¦ saber si un elemento está en un vector ¦ #include <algorithm>⏎#include <iostream>⏎#include <vector>⏎int main() {⏎    std::vector<int> v{1, 2, 2, 3};⏎    std::cout << (std::find(v.begin(), v.end(), 3) != v.end()) << " " << std::count(v.begin(), v.end(), 2) << "\n";⏎} ¦ busca el 3 y cuenta los 2 ¦ comparar el resultado de find con nullptr
transform y accumulate ¦ std::transform ¦ algoritmos para transformar y acumular ¦ duplicar todos los valores y sumarlos ¦ #include <algorithm>⏎#include <iostream>⏎#include <numeric>⏎#include <vector>⏎int main() {⏎    std::vector<int> v{1, 2, 3};⏎    std::transform(v.begin(), v.end(), v.begin(), [](int x) { return x * 2; });⏎    std::cout << std::accumulate(v.begin(), v.end(), 0) << "\n";⏎} ¦ duplica y suma: 12 ¦ olvidar el valor inicial de accumulate
remove_if y erase ¦ std::erase_if ¦ forma de borrar elementos que cumplen una condición ¦ quitar los números negativos ¦ #include <iostream>⏎#include <vector>⏎int main() {⏎    std::vector<int> v{1, -2, 3, -4};⏎    std::erase_if(v, [](int x) { return x < 0; });⏎    std::cout << v.size() << "\n";⏎} ¦ deja solo los positivos ¦ usar remove_if sin erase y no borrar nada
Rangos de C++20 ¦ std::views ¦ biblioteca para encadenar filtros y transformaciones ¦ obtener los cuadrados de los pares ¦ #include <iostream>⏎#include <ranges>⏎#include <vector>⏎int main() {⏎    std::vector<int> v{1, 2, 3, 4};⏎    for (int x : v | std::views::filter([](int n) { return n % 2 == 0; }) | std::views::transform([](int n) { return n * n; })) std::cout << x << " ";⏎    std::cout << "\n";⏎} ¦ muestra 4 y 16 ¦ guardar una vista de un vector que ya no existe
std::format ¦ std::format ¦ función moderna para armar textos con formato ¦ mostrar un precio con dos decimales ¦ #include <format>⏎#include <iostream>⏎int main() {⏎    std::cout << std::format("Total: {:.2f} | {:>4}", 12.5, 7) << "\n";⏎} ¦ formatea el precio y alinea un número ¦ usar printf con tipos que no coinciden
std::chrono ¦ chrono ¦ biblioteca para tiempos y duraciones ¦ medir cuánto tarda una función ¦ #include <chrono>⏎#include <iostream>⏎int main() {⏎    using namespace std::chrono;⏎    auto d = 90min;⏎    std::cout << duration_cast<hours>(d).count() << "h\n";⏎} ¦ convierte 90 minutos en horas ¦ usar números sueltos sin unidades
Números aleatorios modernos ¦ mt19937 ¦ generadores de números aleatorios de calidad ¦ tirar un dado en un juego ¦ #include <iostream>⏎#include <random>⏎int main() {⏎    std::mt19937 g(42);⏎    std::uniform_int_distribution<int> dado(1, 6);⏎    std::cout << (dado(g) >= 1) << "\n";⏎} ¦ genera un número entre 1 y 6 ¦ usar rand() % 6 con poca calidad
std::span ¦ std::span ¦ vista de una secuencia sin copiarla ¦ pasar arreglos a funciones de forma segura ¦ #include <iostream>⏎#include <span>⏎int suma(std::span<const int> s) { int t = 0; for (int x : s) t += x; return t; }⏎int main() { int a[] = {1, 2, 3}; std::cout << suma(a) << "\n"; } ¦ suma un arreglo pasado como span ¦ pasar puntero y tamaño por separado
std::any y std::expected ¦ std::expected ¦ tipos para valores de cualquier tipo o resultados con error ¦ devolver un error sin excepciones ¦ #include <expected>⏎#include <iostream>⏎std::expected<int, std::string> dividir(int a, int b) { if (!b) return std::unexpected("división por cero"); return a / b; }⏎int main() { auto r = dividir(4, 0); std::cout << (r ? std::to_string(*r) : r.error()) << "\n"; } ¦ devuelve el error sin lanzar excepción ¦ leer el valor sin comprobar si hay error
Sobrecarga de operador << ¦ operator<< ¦ forma de imprimir tus clases con cout ¦ mostrar un punto con formato propio ¦ #include <iostream>⏎struct P { int x, y; };⏎std::ostream &operator<<(std::ostream &o, const P &p) { return o << "(" << p.x << ", " << p.y << ")"; }⏎int main() { std::cout << P{1, 2} << "\n"; } ¦ imprime el punto con paréntesis ¦ olvidar devolver el flujo
""")

E7 = filas(r"""
Conceptos de C++20 ¦ concept ¦ restricciones con nombre para plantillas ¦ aceptar solo números en una función genérica ¦ #include <concepts>⏎#include <iostream>⏎template <typename T> concept Numero = std::integral<T> || std::floating_point<T>;⏎template <Numero T> T doble(T x) { return x * 2; }⏎int main() { std::cout << doble(4) << " " << doble(1.5) << "\n"; } ¦ duplica solo valores numéricos ¦ recibir mensajes de error enormes sin conceptos
Plantillas variádicas ¦ ... ¦ plantillas que aceptan cualquier cantidad de argumentos ¦ sumar cualquier cantidad de números ¦ #include <iostream>⏎template <typename... T> auto suma(T... x) { return (x + ...); }⏎int main() { std::cout << suma(1, 2, 3, 4) << "\n"; } ¦ suma cuatro números ¦ olvidar los paréntesis del fold expression
Especialización de plantillas ¦ template <> ¦ versión especial de una plantilla para un tipo ¦ dar un comportamiento distinto para bool ¦ #include <iostream>⏎template <typename T> const char *tipo() { return "otro"; }⏎template <> const char *tipo<bool>() { return "bool"; }⏎int main() { std::cout << tipo<int>() << " " << tipo<bool>() << "\n"; } ¦ responde distinto para bool ¦ especializar cuando una sobrecarga basta
if constexpr ¦ if constexpr ¦ condición que se evalúa al compilar ¦ escribir código distinto según el tipo ¦ #include <iostream>⏎#include <type_traits>⏎template <typename T> void info(T) { if constexpr (std::is_integral_v<T>) std::cout << "entero\n"; else std::cout << "otro\n"; }⏎int main() { info(3); info(2.5); } ¦ elige el mensaje al compilar ¦ usar if normal y que no compile para algunos tipos
Rule of five ¦ operator= ¦ las cinco funciones especiales que manejan copia y movimiento ¦ manejar recursos propios correctamente ¦ #include <iostream>⏎#include <utility>⏎struct B { int *d; B() : d(new int(5)) {} ~B() { delete d; } B(B &&o) noexcept : d(std::exchange(o.d, nullptr)) {} B &operator=(B &&o) noexcept { std::swap(d, o.d); return *this; } B(const B &) = delete; B &operator=(const B &) = delete; };⏎int main() { B a; B b = std::move(a); std::cout << *b.d << "\n"; } ¦ mueve el recurso sin copiarlo ¦ escribir el destructor y olvidar la copia
Herencia múltiple y virtual ¦ virtual public ¦ heredar de varias clases evitando duplicados ¦ resolver el problema del diamante ¦ #include <iostream>⏎struct A { int v = 1; };⏎struct B : virtual A {}; struct C : virtual A {};⏎struct D : B, C {};⏎int main() { std::cout << D{}.v << "\n"; } ¦ comparte una sola copia de A ¦ crear jerarquías complejas sin necesidad
Patrón Observer ¦ std::function ¦ patrón que avisa a varios objetos cuando algo cambia ¦ actualizar la interfaz al cambiar los datos ¦ #include <functional>⏎#include <iostream>⏎#include <vector>⏎int main() {⏎    std::vector<std::function<void(int)>> obs;⏎    obs.push_back([](int v) { std::cout << "valor " << v << "\n"; });⏎    for (auto &f : obs) f(7);⏎} ¦ avisa a los observadores del nuevo valor ¦ guardar referencias a objetos que ya no existen
Patrón Factory ¦ make_unique ¦ patrón que crea objetos sin decir su clase concreta ¦ crear figuras según un texto ¦ #include <iostream>⏎#include <memory>⏎#include <string>⏎struct F { virtual double area() const = 0; virtual ~F() = default; };⏎struct C : F { double area() const override { return 3.14; } };⏎std::unique_ptr<F> crear(const std::string &n) { if (n == "c") return std::make_unique<C>(); return nullptr; }⏎int main() { std::cout << crear("c")->area() << "\n"; } ¦ crea la figura según su nombre ¦ olvidar el destructor virtual en la base
async y future ¦ std::async ¦ forma de ejecutar tareas en segundo plano y esperar el resultado ¦ calcular algo pesado sin bloquear ¦ #include <future>⏎#include <iostream>⏎int main() {⏎    auto f = std::async(std::launch::async, [] { return 21 * 2; });⏎    std::cout << f.get() << "\n";⏎} ¦ calcula en otro hilo y espera el resultado ¦ ignorar el future y bloquear sin querer
atomic ¦ std::atomic ¦ tipo seguro para contadores compartidos entre hilos ¦ contar desde varios hilos sin candados ¦ #include <atomic>⏎#include <iostream>⏎#include <thread>⏎#include <vector>⏎int main() {⏎    std::atomic<int> c = 0;⏎    std::vector<std::thread> h;⏎    for (int i = 0; i < 4; i++) h.emplace_back([&] { for (int k = 0; k < 1000; k++) c++; });⏎    for (auto &t : h) t.join();⏎    std::cout << c << "\n";⏎} ¦ cuenta 4000 sin perder incrementos ¦ usar int normal entre hilos
jthread ¦ std::jthread ¦ hilo que se une solo al destruirse ¦ evitar olvidar join ¦ #include <iostream>⏎#include <thread>⏎int main() {⏎    { std::jthread h([] { std::cout << "trabajando\n"; }); }⏎    std::cout << "fin\n";⏎} ¦ ejecuta el hilo y lo espera al salir del bloque ¦ usar std::thread y olvidar join
Sistema de archivos ¦ std::filesystem ¦ biblioteca para recorrer carpetas y archivos ¦ listar los archivos de un proyecto ¦ #include <filesystem>⏎#include <iostream>⏎namespace fs = std::filesystem;⏎int main() {⏎    auto p = fs::temp_directory_path();⏎    std::cout << fs::exists(p) << "\n";⏎} ¦ comprueba que existe la carpeta temporal ¦ armar rutas con + en vez de /
Expresiones regulares en C++ ¦ std::regex ¦ biblioteca para validar y buscar patrones ¦ validar una placa de carro ¦ #include <iostream>⏎#include <regex>⏎int main() {⏎    std::cout << std::regex_match("ABC123", std::regex("[A-Z]{3}[0-9]{3}")) << "\n";⏎} ¦ valida el formato de la placa ¦ crear la regex dentro de un bucle muy repetido
Módulos de C++20 ¦ import ¦ alternativa moderna a los archivos de cabecera ¦ compilar más rápido proyectos grandes ¦ // export module matematica;⏎// export int doble(int x) { return x * 2; }⏎// import matematica; ¦ exporta e importa un módulo ¦ mezclar módulos e includes sin configurar el compilador
Gestores de paquetes vcpkg y Conan ¦ vcpkg ¦ herramientas para instalar librerías de C++ ¦ usar librerías como fmt o json fácilmente ¦ // vcpkg install fmt nlohmann-json⏎// find_package(fmt CONFIG REQUIRED) en CMakeLists.txt ¦ instala librerías y las enlaza ¦ copiar archivos de librerías a mano
JSON con nlohmann ¦ nlohmann::json ¦ librería popular para leer y escribir JSON ¦ guardar la configuración de un juego ¦ // #include <nlohmann/json.hpp>⏎// auto j = nlohmann::json::parse(R"({"vidas":3})");⏎// std::cout << j["vidas"]; ¦ lee un valor del JSON ¦ acceder a claves que no existen sin revisar
Perfilado y rendimiento ¦ perf ¦ herramientas para encontrar qué parte del código es lenta ¦ optimizar un juego o simulación ¦ // g++ -O2 -g main.cpp -o app⏎// perf record ./app && perf report ¦ mide dónde gasta tiempo el programa ¦ optimizar a ciegas sin medir
Desarrollo de videojuegos ¦ SFML ¦ C++ se usa en motores de juegos como Unreal ¦ crear un juego con gráficos ¦ // sf::RenderWindow w(sf::VideoMode({800, 600}), "Juego");⏎// while (w.isOpen()) { w.clear(); w.draw(figura); w.display(); } ¦ abre una ventana y dibuja cada cuadro ¦ hacer cálculos pesados dentro del bucle de dibujo
Proyecto final con C++ ¦ cmake --build ¦ programa completo con clases, STL, archivos y pruebas ¦ practicar todo lo aprendido ¦ #include <iostream>⏎#include <string>⏎#include <vector>⏎struct Tarea { std::string texto; bool hecha; };⏎int main() {⏎    std::vector<Tarea> t{{"Estudiar C++", false}};⏎    for (const auto &x : t) std::cout << (x.hecha ? "[x] " : "[ ] ") << x.texto << "\n";⏎} ¦ muestra una lista de tareas ¦ usar new y delete en vez de contenedores
""")

